#!/usr/bin/env node
import process from 'node:process';
import { isValidKey, loadStore, purgeExpired, saveStore } from '../lib/store.js';

const USAGE = `Usage: node bin/kv.js <command> [args] [--file <path>]

Commands:
  set <key> <value...> [--ttl <seconds>]  Store a value (all value
                                           arguments joined with spaces)
  get <key>                               Print the value for a key
  del <key>                               Remove a key
  list                                    List all non-expired keys

Options:
  --file <path>    Path to the JSON store file (default: .kv.json)
  --ttl <seconds>  Expire the key this many seconds after it is set
`;

function usageError() {
  process.stderr.write(USAGE);
  return 2;
}

function parseArgs(argv) {
  const rest = [];
  let file = null;
  let ttl = null;
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--file') {
      if (i + 1 >= argv.length) return { error: 'missing value for --file' };
      file = argv[i + 1];
      i += 1;
    } else if (arg === '--ttl') {
      if (i + 1 >= argv.length) return { error: 'missing value for --ttl' };
      ttl = argv[i + 1];
      i += 1;
    } else {
      rest.push(arg);
    }
  }
  return { rest, file, ttl };
}

function resolveFile(file) {
  return file ?? '.kv.json';
}

function fail(message) {
  process.stderr.write(`${message}\n`);
  return 1;
}

function cmdSet(file, args, ttlArg) {
  if (args.length < 1) return usageError();
  const [key, ...valueParts] = args;
  const value = valueParts.join(' ');
  if (!isValidKey(key)) return fail(`invalid key: ${key}`);

  let expiresAt = null;
  if (ttlArg !== null) {
    const seconds = Number(ttlArg);
    if (!Number.isFinite(seconds) || seconds < 0) {
      return fail(`invalid ttl: ${ttlArg}`);
    }
    expiresAt = Date.now() + Math.round(seconds * 1000);
  }

  const data = loadStore(file);
  purgeExpired(data);
  data[key] = { value, expiresAt };
  saveStore(file, data);
  return 0;
}

function cmdGet(file, args) {
  if (args.length !== 1) return usageError();
  const key = args[0];
  if (!isValidKey(key)) return fail(`invalid key: ${key}`);

  const data = loadStore(file);
  const changed = purgeExpired(data);
  const entry = data[key];
  if (!entry) {
    if (changed) saveStore(file, data);
    return fail(`not found: ${key}`);
  }
  if (changed) saveStore(file, data);
  process.stdout.write(`${entry.value}\n`);
  return 0;
}

function cmdDel(file, args) {
  if (args.length !== 1) return usageError();
  const key = args[0];
  if (!isValidKey(key)) return fail(`invalid key: ${key}`);

  const data = loadStore(file);
  const changed = purgeExpired(data);
  if (!data[key]) {
    if (changed) saveStore(file, data);
    return fail(`not found: ${key}`);
  }
  delete data[key];
  saveStore(file, data);
  process.stdout.write('deleted\n');
  return 0;
}

function cmdList(file, args) {
  if (args.length !== 0) return usageError();
  const data = loadStore(file);
  const changed = purgeExpired(data);
  if (changed) saveStore(file, data);
  for (const key of Object.keys(data).sort()) {
    process.stdout.write(`${key}\n`);
  }
  return 0;
}

function main(argv) {
  const parsed = parseArgs(argv);
  if (parsed.error) {
    process.stderr.write(`${parsed.error}\n`);
    return usageError();
  }
  const file = resolveFile(parsed.file);
  const { rest } = parsed;
  if (rest.length === 0) return usageError();

  const command = rest[0];
  const args = rest.slice(1);
  switch (command) {
    case 'set':
      return cmdSet(file, args, parsed.ttl);
    case 'get':
      return cmdGet(file, args);
    case 'del':
      return cmdDel(file, args);
    case 'list':
      return cmdList(file, args);
    default:
      return usageError();
  }
}

process.exitCode = main(process.argv.slice(2));
